<?phpadd_action('add_meta_boxes', 'tns_add_meta_box_popular');function tns_add_meta_box_popular() {	add_meta_box(		'tns_add_meta_box_popular',		'محبوب ترین محصول شما',		'tns_add_meta_box_popular_layout',		'product',		'normal',		'high'	);}function tns_add_meta_box_popular_layout($post) {	$show_popular = get_post_meta($post->ID, '_tns_check_popular', true);    $show_product_expert = get_post_meta($post->ID, '_tns_show_product_expert', true);	wp_nonce_field('tns_nonce_popular_action', 'tns_nonce_popular_action');    wp_nonce_field('tns_show_product_expert_action', 'tns_show_product_expert_action');	?>    <div>        <h3 class="hndle ui-sortable-handle">محبوب ترین محصولات : </h3>        <label>            <input type="checkbox" name="show_popular" value="1" <?php checked($show_popular, 1); ?>>            <span>محبوب ترین محصول از دید شما آن را انتخاب کنید!</span>        </label>        <?php        $index = get_option('_tnm_set_index_website');        if ($index === 'in20') : ?>        <br>        <h3 class="hndle ui-sortable-handle">پیشنهاد کارشناس های ما : </h3>        <label>            <input type="checkbox" name="show_product_expert" value="1" <?php checked($show_product_expert, 1); ?>>            <span>بخش پیشنهاد های کارشناس های ما</span>        </label>      <?php endif; ?>    </div>	<?php}add_action('save_post', 'tns_add_meta_box_popular_save_post');function tns_add_meta_box_popular_save_post($post_id) {	// Verify nonce	if (!isset($_POST['tns_nonce_popular_action']) ||        !wp_verify_nonce($_POST['tns_nonce_popular_action'], 'tns_nonce_popular_action') ||        !isset($_POST['tns_show_product_expert_action']) ||        !wp_verify_nonce($_POST['tns_show_product_expert_action'], 'tns_show_product_expert_action')){		return;	}	// Check autosave	if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {		return;	}	// Check permissions	if (!current_user_can('edit_post', $post_id)) {		return;	}	// Save or delete meta	if (isset($_POST['show_popular'])) {		update_post_meta($post_id, '_tns_check_popular', 1);	} else {		update_post_meta($post_id, '_tns_check_popular', 0);	}    $index = get_option('_tnm_set_index_website');    if ($index === 'in20') {        if (isset($_POST['show_product_expert'])) {            update_post_meta($post_id, '_tns_show_product_expert', 1);        } else {            update_post_meta($post_id, '_tns_show_product_expert', 0);        }    }}add_action('add_meta_boxes','tns_add_meta_box_send_post_newsletter');function tns_add_meta_box_send_post_newsletter() {	add_meta_box(            'tns_send_post_newsletter'        ,'انتخاب پست در خبر نامه'        ,'tns_send_post_newsletter_layout'		,'post',		'normal',		'high'    );}function tns_send_post_newsletter_layout($post) {   $send_newsletter = get_post_meta($post->ID,'_tns_send_post_newsletter',true);   wp_nonce_field('tns_nonce_send_post_newsletter_action','tns_nonce_send_post_newsletter_action'); ?>    <div>        <label>            <input name="send_post_newsletter" type="checkbox" value="1" <?php checked($send_newsletter , 1) ?>>            <span>پستی که میخوایید در خبرنامه ارسال کنید با فعال کردن این پست ارسال میشود!</span>        </label>    </div><?php }add_action('save_post','tns_send_post_newsletter_save_post');function tns_send_post_newsletter_save_post($post_id) {	// Verify nonce	if (!isset($_POST['tns_nonce_send_post_newsletter_action']) || !wp_verify_nonce($_POST['tns_nonce_send_post_newsletter_action'], 'tns_nonce_send_post_newsletter_action')) {		return;	}	// Check autosave	if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {		return;	}	// Check permissions	if (!current_user_can('edit_post', $post_id)) {		return;	}	// Save or delete meta	if (isset($_POST['send_post_newsletter'])) {		update_post_meta($post_id, '_tns_send_post_newsletter', 1);	} else {		update_post_meta($post_id, '_tns_send_post_newsletter', 0);	}}// ADD AUTHOR NAME$index = get_option('_tnm_set_index_website');if ($index === 'in20') {    add_action('add_meta_boxes','tns_add_author_name');    function tns_add_author_name(): void{        add_meta_box(            'tns_author_name',            'نویسندگان کتاب',            'tns_render_author_meta_box',            'product',            'normal',            'default'        );    }    function tns_render_author_meta_box($post): void{        $authors = get_post_meta($post->ID, '_tns_book_authors', true);        wp_nonce_field('tns_nonce_add_author_action', 'tns_nonce_add_author_action');    ?>        <p>            <label for="tns_book_authors">                نام نویسندگان (با ، یا و جدا کنید):            </label>        </p>        <input                type="text"                id="tns_book_authors"                name="tns_book_authors"                value="<?php echo esc_attr($authors); ?>"                style="width:100%;"                placeholder="مثال: بکی آلبرتالی، آدام سیلورا"        >    <?php    }    function tns_add_author_name_save($post_id): void{        if (!isset($_POST['tns_nonce_add_author_action']) ||            !wp_verify_nonce($_POST['tns_nonce_add_author_action'], 'tns_nonce_add_author_action')) {            return;        }        if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) {            return;        }        if (!current_user_can('edit_post', $post_id)) {            return;        }        if (isset($_POST['tns_book_authors'])) {            update_post_meta(                $post_id,                '_tns_book_authors',                sanitize_text_field($_POST['tns_book_authors'])            );        }    }    add_action('save_post','tns_add_author_name_save');}